import React, { useState, useEffect } from 'react';
import restaurantService from '../../../services/restaurantService';
import { useAuth } from '../../hooks/useAuth';
import { useNavigate, useParams } from 'react-router-dom';

const EditRestaurant = () => {
  const { id } = useParams();
  const [name, setName] = useState('');
  const [address, setAddress] = useState('');
  const [contactNumber, setContactNumber] = useState('');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const { token } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    const fetchRestaurant = async () => {
      setLoading(true);
      setError('');
      try {
        const restaurant = await restaurantService.getRestaurantByOwner(token);
        if (restaurant && restaurant._id === id) {
          setName(restaurant.name);
          setAddress(restaurant.address);
          setContactNumber(restaurant.contactNumber || '');
        } else {
          setError('Restaurant not found or unauthorized.');
          navigate('/restaurant/dashboard'); // Redirect if not the owner
        }
      } catch (err) {
        setError(err.message || 'Failed to fetch restaurant details.');
      } finally {
        setLoading(false);
      }
    };

    fetchRestaurant();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token, id, navigate]);

  const handleSubmit = async (event) => {
    event.preventDefault();
    setSaving(true);
    setError('');
    try {
      const updatedRestaurant = { name, address, contactNumber };
      await restaurantService.updateRestaurant(id, updatedRestaurant, token);
      console.log('Restaurant updated successfully.');
      setSaving(false);
      navigate('/restaurant/dashboard'); // Redirect after update
    } catch (err) {
      setError(err.message || 'Failed to update restaurant.');
      setSaving(false);
    }
  };

  if (loading) {
    return <div>Loading restaurant details...</div>;
  }

  if (error) {
    return <div style={{ color: 'red' }}>{error}</div>;
  }

  return (
    <div>
      <h2>Edit Restaurant</h2>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="name">Name:</label>
          <input type="text" id="name" value={name} onChange={(e) => setName(e.target.value)} required />
        </div>
        <div>
          <label htmlFor="address">Address:</label>
          <input type="text" id="address" value={address} onChange={(e) => setAddress(e.target.value)} required />
        </div>
        <div>
          <label htmlFor="contactNumber">Contact Number:</label>
          <input type="text" id="contactNumber" value={contactNumber} onChange={(e) => setContactNumber(e.target.value)} />
        </div>
        <button type="submit" disabled={saving}>
          {saving ? 'Saving...' : 'Save Changes'}
        </button>
      </form>
    </div>
  );
};

export default EditRestaurant;
